KDPP3_PAYLOAD_BASE64
echo "$PAYLOAD_SHA256  $STAGE/payload.tar.gz" | sha256sum -c - >/dev/null || { echo FAIL_PAYLOAD_SHA256; exit 85; }
tar --warning=no-timestamp -xzf "$STAGE/payload.tar.gz" -C "$STAGE" || { echo FAIL_EXTRACT; exit 86; }
echo "PAYLOAD_OK sha256=$PAYLOAD_SHA256 bytes=$(stat -c %s "$STAGE/payload.tar.gz")"
"$PY" -I -B - "$STAGE" <<'KDPP3_VERIFY'
import hashlib, json, sys
root = sys.argv[1]
manifest = json.load(open(root + '/deploy_manifest.sha256.json'))
bad = [k for k, v in manifest.items() if hashlib.sha256(open(root + '/' + k, 'rb').read()).hexdigest() != v]
print('DEPLOY_MANIFEST members=%d mismatched=%d' % (len(manifest), len(bad)))
sys.exit(1 if bad else 0)
KDPP3_VERIFY
rc=$?; echo "VERIFY_EXIT=$rc"; [ "$rc" -eq 0 ] || exit 87
mv "$ROOT/workspace" "$ROOT/workspace_superseded_seq137" || exit 88
